// An original, entirely 2D drawing. No image inputs, model calls, meshes or camera.
// Landmarks, silhouettes and anatomical planes are authored; surface marks are seeded.
const c = art.canvas(), ctx = c.getContext('2d');
const W = 1400, H = 1050, stage = parameters.stage ?? 'paint', revision = parameters.revision ?? 0;
ctx.scale(art.width / W, art.height / H);
const rand = (a, b) => a + art.random() * (b-a);
const clamp = (v,a=0,b=1) => Math.max(a,Math.min(b,v));
const rgb = (r,g,b) => `rgb(${Math.round(clamp(r,0,255))},${Math.round(clamp(g,0,255))},${Math.round(clamp(b,0,255))})`;
function fill(d,col){ctx.fillStyle=col;ctx.fill(art.path(d));}
function line(d,col,w=1,alpha=1){ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=col;ctx.lineWidth=w;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke(art.path(d));ctx.restore();}
function gradient(x1,y1,x2,y2,stops){const g=ctx.createLinearGradient(x1,y1,x2,y2);stops.forEach((v,i)=>g.addColorStop(i/(stops.length-1),v));return g;}
function radial(x,y,r,stops){const g=ctx.createRadialGradient(x,y,0,x,y,r);stops.forEach((v,i)=>g.addColorStop(i/(stops.length-1),v));return g;}
function poly(p,col){fill('M'+p.map(v=>v.join(' ')).join('L')+'Z',col);}
function ellipse(x,y,rx,ry,col,a=0){ctx.fillStyle=col;ctx.beginPath();ctx.ellipse(x,y,rx,ry,a,0,Math.PI*2);ctx.fill();}
// Background: broad, low-contrast marks, with the light concentrated below the muzzle.
ctx.fillStyle=gradient(0,0,W,H,['#4d4940','#282c29','#131c1b']);ctx.fillRect(0,0,W,H);
if(stage==='paint'){
 for(let i=0;i<2500;i++){
  const x=rand(-70,W+70),y=rand(-50,H+50),s=rand(8,85),v=art.fbm(x/210,y/190,3);
  const warm=clamp(1-Math.hypot(x-190,y-100)/950),glow=clamp(1-Math.hypot(x-1230,y-750)/750);
  ctx.save();ctx.globalAlpha=rand(.025,.12);
  poly([[x-s,y],[x-s*.2,y-s*.22],[x+s,y-s*.1],[x+s*.55,y+s*.22],[x-s*.6,y+s*.3]],rgb(32+v*38+warm*45+glow*18,38+v*32+warm*22+glow*40,34+v*28));ctx.restore();
 }
}
ctx.fillStyle=radial(1170,740,550,['#9da74b38','#53704318','#31553300']);ctx.fillRect(0,0,W,H);
// Separate far horns establish overlap; their soft values recede behind the skull.
const farHorn='M592 344 C522 274 450 193 372 174 C440 261 459 330 495 394Z';
fill(farHorn,gradient(430,190,550,390,['#737263','#252e2a','#121c1a']));
fill('M699 327 C684 254 669 224 608 168 C635 243 602 290 639 349Z',gradient(610,190,680,340,['#5e6658','#222e28']));
// Neck, cranium, cheek and lower jaw are separate silhouettes, with one shared hinge.
const neck='M-70 1130 L-50 720 C31 638 150 624 209 551 C273 471 275 397 390 363 C457 342 551 363 591 423 C666 528 640 634 563 716 C499 786 460 880 511 1069Z';
const skull=revision?'M353 416 C376 344 437 311 501 314 L550 281 L593 297 L624 281 L661 310 L703 307 L748 327 L787 360 L818 373 L860 375 L889 389 L922 387 L945 401 L975 403 L987 396 L1009 410 L1024 431 L1019 448 L1024 465 L1007 485 L991 487 L978 500 L953 506 L925 500 L907 506 L878 493 L850 497 L816 484 L786 491 L749 480 L729 495 L707 501 L692 528 L666 531 L633 558 L597 546 L577 538 L527 490 L458 472 L393 458Z':'M353 416 C376 344 437 311 501 314 L550 281 L593 297 L624 281 L661 310 L703 307 L758 336 L800 366 L866 381 L916 386 L950 408 L1005 410 Q1033 431 1020 470 L997 496 L950 514 L878 503 L815 494 L742 490 L692 528 L633 558 L577 538 L527 490 L458 472 L393 458Z';
const jaw='M585 498 C638 508 660 556 706 594 L829 654 L924 687 L946 714 L930 743 L887 753 L821 720 L738 692 L648 650 Q600 620 571 572Z';
